/** Brass urli with turmeric paste and floating marigolds. Origin = centre of the rim; width ≈ 2·r. */
export const Urli: React.FC<{ r?: number; t?: number }> = ({ r = 110, t = 0 }) => {
  const ry = r * 0.3;
  return (
    <g>
      <ellipse cx={0} cy={r * 0.62} rx={r * 0.9} ry={ry * 0.5} fill={palette.ink} opacity={0.2} />
      {/* bowl body */}
      <path d={`M${-r} 0 C${-r * 0.95} ${r * 0.45} ${-r * 0.5} ${r * 0.58} 0 ${r * 0.58} C${r * 0.5} ${r * 0.58} ${r * 0.95} ${r * 0.45} ${r} 0 Z`} fill={palette.brass} />
      <path d={`M${-r} 0 C${-r * 0.95} ${r * 0.45} ${-r * 0.5} ${r * 0.58} 0 ${r * 0.58} C${-r * 0.3} ${r * 0.5} ${-r * 0.7} ${r * 0.3} ${-r * 0.8} 0 Z`} fill="#000" opacity={0.15} />
      <path d={`M${r * 0.35} ${r * 0.1} C${r * 0.55} ${r * 0.2} ${r * 0.7} ${r * 0.3} ${r * 0.78} ${r * 0.12}`} fill="none" stroke={palette.goldPale} strokeWidth={4} strokeLinecap="round" opacity={0.7} />
      {/* engraved band */}
      <path d={`M${-r * 0.86} ${r * 0.22} C${-r * 0.5} ${r * 0.36} ${r * 0.5} ${r * 0.36} ${r * 0.86} ${r * 0.22}`} fill="none" stroke={palette.goldDeep} strokeWidth={1.4} strokeDasharray="2 5" />
      {/* foot */}
      <path d={`M${-r * 0.3} ${r * 0.55} L${r * 0.3} ${r * 0.55} L${r * 0.36} ${r * 0.66} L${-r * 0.36} ${r * 0.66} Z`} fill={palette.goldDeep} />
      {/* rim and paste */}
      <ellipse cx={0} cy={0} rx={r} ry={ry} fill="url(#foil)" />
      <ellipse cx={0} cy={2} rx={r * 0.9} ry={ry * 0.78} fill="#D08C1E" />
      <ellipse cx={0} cy={4} rx={r * 0.86} ry={ry * 0.7} fill={palette.turmeric} />
      <path d={`M${-r * 0.6} ${-2} C${-r * 0.3} ${-10} ${r * 0.2} ${10} ${r * 0.55} ${-2}`} fill="none" stroke="#F4C75A" strokeWidth={3} opacity={0.8} strokeLinecap="round" />
      <path d={`M${-r * 0.4} ${ry * 0.35} C${-r * 0.1} ${ry * 0.1} ${r * 0.2} ${ry * 0.55} ${r * 0.45} ${ry * 0.3}`} fill="none" stroke="#C07A14" strokeWidth={2} opacity={0.6} strokeLinecap="round" />
      {/* floating marigolds bob gently */}
      {[
        [-r * 0.45, -2, 14, "orange"],
        [r * 0.05, 6, 16, "yellow"],
        [r * 0.5, -1, 13, "orange"],
        [-r * 0.12, -12, 10, "orange"],
      ].map(([x, y, s, tone], i) => (
        <g key={i} transform={`translate(0 ${Math.sin(t / 18 + i * 1.3) * 1.6})`}>
          <ellipse cx={x as number} cy={(y as number) + 5} rx={(s as number) * 1.1} ry={(s as number) * 0.35} fill="#A8660F" opacity={0.35} />
          <g transform={`translate(${x} ${y}) scale(1 0.62)`}>
            <Flower x={0} y={0} r={s as number} tone={tone as "orange" | "yellow"} rot={i * 30 + t * 0.2} />
          </g>
        </g>
      ))}
      <ellipse cx={0} cy={0} rx={r} ry={ry} fill="none" stroke={palette.goldDeep} strokeWidth={1.2} />
    </g>
  );
};

