/* ───────────── Mehendi hand ───────────── */

const HENNA = "#6B2A1A";
const SKIN = "#E2B394";
const SKIN_LINE = "#C89272";

// Hand geometry in a 340×470 box, wrist at the bottom, thumb on the viewer's right.
const FINGERS = [
  { x: 52, w: 46, top: 120 },
  { x: 102, w: 48, top: 58 },
  { x: 154, w: 48, top: 36 },
  { x: 206, w: 46, top: 72 },
];
const PALM = "M48 200 C44 260 46 330 70 380 C84 410 90 440 92 470 L230 470 C232 440 240 410 256 382 C270 356 272 320 262 290 L250 200 Z";
const THUMB = "M240 318 C250 290 268 262 290 236 C302 222 322 226 326 242 C330 258 318 272 306 290 C290 316 276 346 258 372 Z";

/** One stroke that draws itself between `a` and `b` of the master progress `p`. */
const Ink: React.FC<{ d: string; p: number; a: number; b: number; w?: number; fill?: boolean }> = ({ d, p, a, b, w = 2.2, fill }) => {
  const t = Math.min(1, Math.max(0, (p - a) / (b - a)));
  if (t <= 0) return null;
  return (
    <g>
      {fill ? <path d={d} fill={HENNA} opacity={Math.max(0, t - 0.7) / 0.3} /> : null}
      <path d={d} pathLength={1} fill="none" stroke={HENNA} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 1" strokeDashoffset={1 - t} />
    </g>
  );
};

const circlePath = (cx: number, cy: number, r: number) => `M${cx} ${cy - r} A${r} ${r} 0 1 1 ${cx - 0.01} ${cy - r} Z`;

/**
 * A large illustrated hand whose mehendi draws itself (`draw` 0→1): palm mandala first, then the
 * fingers and thumb, then the wrist cuffs.
 */
export const MehendiHand: React.FC<{ draw: number }> = ({ draw: p }) => {
  const mx = 156;
  const my = 300;
  const petals = new Array(12).fill(0).map((_, i) => {
    const a = (i / 12) * Math.PI * 2;
    const c = Math.cos(a);
    const s = Math.sin(a);
    const r0 = 38;
    const r1 = 62;
    const px = (r: number, off: number) => mx + Math.cos(a + off) * r;
    const py = (r: number, off: number) => my + Math.sin(a + off) * r;
    return `M${px(r0, -0.2)} ${py(r0, -0.2)} Q${mx + c * (r1 - 4) - s * 12} ${my + s * (r1 - 4) + c * 12} ${mx + c * r1} ${my + s * r1} Q${mx + c * (r1 - 4) + s * 12} ${my + s * (r1 - 4) - c * 12} ${px(r0, 0.2)} ${py(r0, 0.2)}`;
  });
  return (
    <g>
      {/* outline via stroke-under, then flat skin */}
      <g stroke={SKIN_LINE} strokeWidth={5} fill={SKIN_LINE}>
        {FINGERS.map((f, i) => (
          <rect key={i} x={f.x} y={f.top} width={f.w} height={230 - f.top} rx={f.w / 2} />
        ))}
        <path d={PALM} />
        <path d={THUMB} />
      </g>
      <g fill={SKIN}>
        {FINGERS.map((f, i) => (
          <rect key={i} x={f.x} y={f.top} width={f.w} height={230 - f.top} rx={f.w / 2} />
        ))}
        <path d={PALM} />
        <path d={THUMB} />
      </g>
      {/* palm creases */}
      <g fill="none" stroke={SKIN_LINE} strokeWidth={1.4} opacity={0.6}>
        <path d="M60 250 C110 262 170 250 236 232" />
        <path d="M232 330 C200 360 190 400 196 440" />
      </g>

      {/* ── mehendi ── */}
      {/* mandala */}
      <Ink d={circlePath(mx, my, 10)} p={p} a={0} b={0.06} fill />
      <Ink d={circlePath(mx, my, 22)} p={p} a={0.04} b={0.12} />
      <Ink d={circlePath(mx, my, 30)} p={p} a={0.08} b={0.16} w={1.4} />
      {petals.map((d, i) => (
        <Ink key={i} d={d} p={p} a={0.12 + i * 0.012} b={0.2 + i * 0.012} w={1.8} />
      ))}
      {new Array(24).fill(0).map((_, i) => {
        const a = (i / 24) * Math.PI * 2;
        const on = p > 0.3 + i * 0.004;
        return on ? <circle key={i} cx={mx + Math.cos(a) * 72} cy={my + Math.sin(a) * 72} r={2.2} fill={HENNA} /> : null;
      })}
      <Ink d={circlePath(mx, my, 80)} p={p} a={0.32} b={0.42} w={1.2} />
      {/* scallop arc across the top of the palm */}
      <Ink d="M60 222 C80 204 100 222 110 206 C124 190 140 212 156 196 C170 212 188 190 202 206 C214 222 232 204 250 220" p={p} a={0.38} b={0.5} w={1.8} />
      {/* fingers: tip caps, bands, vines */}
      {FINGERS.map((f, i) => {
        const cx = f.x + f.w / 2;
        const a0 = 0.46 + i * 0.05;
        const tip = `M${f.x + 2} ${f.top + f.w / 2 + 12} A${f.w / 2 - 2} ${f.w / 2 - 2} 0 0 1 ${f.x + f.w - 2} ${f.top + f.w / 2 + 12} Z`;
        const band1 = f.top + f.w / 2 + 34;
        const band2 = band1 + 58;
        return (
          <g key={i}>
            <Ink d={tip} p={p} a={a0} b={a0 + 0.06} fill />
            <Ink d={`M${f.x + 4} ${band1} Q${cx} ${band1 + 7} ${f.x + f.w - 4} ${band1}`} p={p} a={a0 + 0.04} b={a0 + 0.08} />
            <Ink d={`M${f.x + 4} ${band1 + 8} Q${cx} ${band1 + 15} ${f.x + f.w - 4} ${band1 + 8}`} p={p} a={a0 + 0.05} b={a0 + 0.09} w={1.4} />
            <Ink
              d={`M${f.x + 6} ${band1 + 24} L${f.x + 14} ${band1 + 16} L${f.x + 22} ${band1 + 24} L${f.x + 30} ${band1 + 16} L${f.x + 38} ${band1 + 24}`}
              p={p}
              a={a0 + 0.07}
              b={a0 + 0.11}
              w={1.4}
            />
            <Ink d={`M${f.x + 4} ${band2} Q${cx} ${band2 + 7} ${f.x + f.w - 4} ${band2}`} p={p} a={a0 + 0.09} b={a0 + 0.13} />
            <Ink d={circlePath(cx, band2 + 20, 5)} p={p} a={a0 + 0.11} b={a0 + 0.15} fill />
          </g>
        );
      })}
      {/* thumb */}
      <Ink d="M300 236 C308 232 318 236 320 246 C312 252 302 250 296 244 Z" p={p} a={0.66} b={0.72} fill />
      <Ink d="M276 268 C284 276 296 280 306 276" p={p} a={0.68} b={0.74} />
      <Ink d="M262 300 C272 308 284 312 294 306" p={p} a={0.7} b={0.76} w={1.4} />
      {/* wrist cuffs with lattice */}
      <Ink d="M76 392 C120 406 200 406 250 390" p={p} a={0.76} b={0.84} w={2.4} />
      <Ink d="M84 420 C126 434 196 434 240 418" p={p} a={0.8} b={0.88} w={2.4} />
      <Ink
        d="M88 400 L100 414 L112 402 L124 416 L136 404 L148 418 L160 404 L172 418 L184 404 L196 416 L208 402 L220 414 L232 400"
        p={p}
        a={0.84}
        b={0.94}
        w={1.4}
      />
      {new Array(9).fill(0).map((_, i) =>
        p > 0.9 + i * 0.008 ? <circle key={i} cx={100 + i * 16} cy={446 + Math.sin(i) * 1.5} r={2.4} fill={HENNA} /> : null,
      )}
    </g>
  );
};

/** Mehendi cone: cellophane cone with a gold thread band. Origin = tip; points toward +x. */
export const MehendiCone: React.FC<{ len?: number; rot?: number }> = ({ len = 150, rot = 0 }) => (
  <g transform={`rotate(${rot})`}>
    <path d={`M0 0 L${len} ${-len * 0.13} L${len} ${len * 0.13} Z`} fill={palette.ink} opacity={0.18} transform="translate(4 8)" />
    <path d={`M0 0 L${len} ${-len * 0.13} L${len} ${len * 0.13} Z`} fill="#4A3522" />
    <path d={`M0 0 L${len} ${-len * 0.13} L${len} ${-len * 0.02} Z`} fill="#6E5236" />
    <path d={`M${len * 0.1} ${-len * 0.01} L${len * 0.95} ${-len * 0.1}`} stroke="#FFFFFF" strokeWidth={2} opacity={0.35} />
    <rect x={len * 0.8} y={-len * 0.125} width={8} height={len * 0.25} fill="url(#foil-v)" />
    <path d={`M${len} ${-len * 0.13} C${len + 18} ${-len * 0.13} ${len + 22} ${len * 0.13} ${len} ${len * 0.13} Z`} fill="#E9DFC8" opacity={0.85} />
    <circle cx={1} cy={0} r={2.2} fill={HENNA} />
  </g>
);

/** Round gaddi bolster: origin = centre; horizontal cylinder. */
export const Bolster: React.FC<{ w?: number; h?: number; color?: string; band?: string }> = ({ w = 220, h = 72, color = "#2F5D4A", band = palette.gold }) => (
  <g>
    <ellipse cx={0} cy={h * 0.52} rx={w * 0.52} ry={h * 0.14} fill={palette.ink} opacity={0.25} />
    <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={h / 2} fill={color} />
    <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={h / 2} fill="url(#brocade-gold)" opacity={0.7} />
    <rect x={-w / 2 + h * 0.3} y={h * 0.1} width={w - h * 0.6} height={h * 0.3} fill="#000" opacity={0.14} />
    <rect x={-w / 2 + h * 0.3} y={-h * 0.36} width={w - h * 0.6} height={h * 0.12} fill="#FFFFFF" opacity={0.12} />
    {[-1, 1].map((s) => (
      <g key={s}>
        <rect x={s * (w / 2 - h * 0.62) - 5} y={-h / 2 + 1} width={10} height={h - 2} fill={band} />
        <ellipse cx={s * (w / 2 - h * 0.12)} cy={0} rx={h * 0.16} ry={h * 0.48} fill={color} />
        <ellipse cx={s * (w / 2 - h * 0.12)} cy={0} rx={h * 0.16} ry={h * 0.48} fill="none" stroke={band} strokeWidth={2} />
        <circle cx={s * (w / 2 - h * 0.1)} cy={0} r={5} fill="url(#foil)" />
        <path d={`M${s * (w / 2 - h * 0.1)} 4 L${s * (w / 2 - h * 0.1) - 5} ${h * 0.7} L${s * (w / 2 - h * 0.1) + 5} ${h * 0.7} Z`} fill={band} />
      </g>
    ))}
  </g>
);

/** Dhol (barrel drum) with rope lacing; origin = centre, horizontal. */
export const Dhol: React.FC<{ w?: number; h?: number }> = ({ w = 170, h = 104 }) => {
  const x0 = -w / 2;
  const x1 = w / 2;
  const body = `M${x0 + 10} ${-h / 2} C${x0 + w * 0.3} ${-h * 0.62} ${x1 - w * 0.3} ${-h * 0.62} ${x1 - 10} ${-h / 2} L${x1 - 10} ${h / 2} C${x1 - w * 0.3} ${h * 0.62} ${x0 + w * 0.3} ${h * 0.62} ${x0 + 10} ${h / 2} Z`;
  const lace = new Array(8)
    .fill(0)
    .map((_, i) => {
      const y = -h / 2 + 6 + (i * (h - 12)) / 7;
      return i % 2 === 0 ? `L${x0 + 26} ${y}` : `L${x1 - 26} ${y}`;
    })
    .join(" ");
  return (
    <g>
      <path d={body} fill="#8E2A3C" />
      <path d={body} fill="url(#dots-gold)" opacity={0.6} />
      <path d={`M${x0 + 26} ${-h / 2 + 6} ${lace}`} fill="none" stroke={palette.goldLight} strokeWidth={2} />
      <ellipse cx={x0 + 10} cy={0} rx={12} ry={h / 2} fill="#E9DFC8" stroke={palette.goldDeep} strokeWidth={2.5} />
      <ellipse cx={x1 - 10} cy={0} rx={12} ry={h / 2} fill="#D9C9A8" stroke={palette.goldDeep} strokeWidth={2.5} />
      <path d={`M${x0 + 10} ${-h / 2} L${x1 - 10} ${-h / 2}`} stroke={palette.gold} strokeWidth={3} />
    </g>
  );
};

/** Scatter of loose petals on a floor (static). */
export const PetalScatter: React.FC<{ pts: [number, number, number][]; colors: string[]; s?: number }> = ({ pts, colors, s = 1 }) => (
  <g>
    {pts.map(([x, y, r], i) => (
      <Petal key={i} x={x} y={y} rot={r} s={s} color={colors[i % colors.length]} />
    ))}
  </g>
);
